code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    frequencies = Counter(value for row in grid for value in row)
    separators = []
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            separators.append((frequencies[grid[0][c]], "vertical", c))
    for r in range(h):
        if len(set(grid[r])) == 1:
            separators.append((frequencies[grid[r][0]], "horizontal", r))
    _, direction, index = min(separators)
    if direction == "vertical":
        first = [row[:index] for row in grid]
        second = [row[index + 1:] for row in grid]
        colors_first = {v for row in first for v in row}
        colors_second = {v for row in second for v in row}
        base = min(colors_first & colors_second, key=lambda v: frequencies[v])
        return [[3 if a == b else base for a, b in zip(arow, brow)] for arow, brow in zip(first, second)]
    first, second = grid[:index], grid[index + 1:]
    colors_first = {v for row in first for v in row}
    colors_second = {v for row in second for v in row}
    base = min(colors_first & colors_second, key=lambda v: frequencies[v])
    return [[3 if a == b else base for a, b in zip(arow, brow)] for arow, brow in zip(first, second)]
'''
